import{_ as a,C as i,o as l,c as u,j as r,a as t,E as o,a2 as n}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Livraison","description":"","frontmatter":{"title":"Livraison"},"headers":[],"relativePath":"guide/release.md","filePath":"guide/release.md"}'),d={name:"guide/release.md"};function c(p,e,g,v,h,m){const s=i("Capture");return l(),u("div",null,[e[0]||(e[0]=r("h1",{id:"livraison",tabindex:"-1"},[t("Livraison "),r("a",{class:"header-anchor",href:"#livraison","aria-label":'Permalink to "Livraison"'},"​")],-1)),e[1]||(e[1]=r("p",null,[t("Cet écran, intitulé "),r("strong",null,"Planification de la livraison"),t(", livre une nouvelle version : celle d'un module (conseillé), ou celle du projet entier. Vous choisissez ce qui se livre, le plan se calcule tout de suite, puis vous l'exécutez après un récapitulatif.")],-1)),o(s,{name:"release",alt:"L'écran Livraison : choix de la cible, plan de livraison et configuration de livraison"}),e[2]||(e[2]=n('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>Que livrer ?</strong> En premier, sous <strong>Modules — conseillé</strong>, les modules du projet avec leur version. En dessous, <strong>Projet entier</strong>. Le premier module est choisi d&#39;office.</li><li><strong>Type d&#39;incrément</strong> : <strong>Patch</strong>, <strong>Mineur</strong> ou <strong>Majeur</strong>.</li><li>Le plan de la cible choisie : <ul><li>la version courante et la version cible, par exemple <code>1.4.0 → 1.4.1</code> ;</li><li>le <strong>Tag</strong> qui sera posé, le <strong>Dernier tag</strong>, le <strong>Dépôt</strong> (dépôt propre du module, ou dépôt du projet), le <strong>Dépôt de release</strong>, la <strong>Branche</strong> et les <strong>Fichiers de version</strong> ;</li><li><strong>À savoir</strong> : ce qu&#39;il faut savoir avant d&#39;exécuter, par exemple une version cible en retard sur le dernier tag ;</li><li>les <strong>Étapes du plan</strong>, chacune avec sa case à cocher.</li></ul></li><li><strong>Configuration de livraison</strong> (plus bas) : la commande de build et les artefacts de chaque module.</li></ul><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="choisir-ce-qui-se-livre" tabindex="-1">Choisir ce qui se livre <a class="header-anchor" href="#choisir-ce-qui-se-livre" aria-label="Permalink to &quot;Choisir ce qui se livre&quot;">​</a></h3><p>Cliquez sur un module, ou sur <strong>Projet entier</strong>. Le plan se recalcule aussitôt, sans rien écrire.</p><p>Ce qui change selon la cible :</p><table tabindex="0"><thead><tr><th>Cible</th><th>Version lue dans</th><th>Tag posé</th><th>Git agit dans</th></tr></thead><tbody><tr><td>Module à dépôt propre</td><td>ses fichiers (<code>package.json</code>, <code>Cargo.toml</code>…)</td><td><code>v1.4.1</code></td><td>son dépôt</td></tr><tr><td>Module dans le dépôt du projet</td><td>ses fichiers</td><td><code>site-v1.4.1</code></td><td>le dépôt du projet, borné au chemin du module</td></tr><tr><td>Projet entier</td><td><code>effortless.json</code> et les fichiers de version déclarés</td><td><code>v0.2.0</code></td><td>le dépôt du projet</td></tr></tbody></table><p>Les fichiers de version d&#39;un module sont détectés. Pour en imposer d&#39;autres, déclarez-les dans <code>stacks[].release.version_files</code> de <code>effortless.json</code>.</p><h3 id="choisir-les-etapes" tabindex="-1">Choisir les étapes <a class="header-anchor" href="#choisir-les-etapes" aria-label="Permalink to &quot;Choisir les étapes&quot;">​</a></h3><p>Cochez les étapes à jouer : <strong>Incrémenter la version</strong>, <strong>Commit et push</strong>, <strong>Tag et release GitHub</strong>, <strong>Mettre à jour la documentation</strong>, <strong>Build et envoi des artefacts</strong>. Une étape qui ne s&#39;applique pas à la cible est grisée. Vos coches sont mémorisées pour ce projet ; sans aucune coche, l&#39;écran demande « Cochez au moins une étape. »</p><h3 id="executer" tabindex="-1">Exécuter <a class="header-anchor" href="#executer" aria-label="Permalink to &quot;Exécuter&quot;">​</a></h3><ol><li>Cliquez sur <strong>Exécuter…</strong>. Un panneau récapitule la cible, la version, le tag, le dépôt et les étapes.</li><li>Lisez-le : ces actions sont réelles (écriture des fichiers de version, commit, push, tag, release GitHub, build) et ne s&#39;annulent pas d&#39;un clic.</li><li>Cliquez sur <strong>Confirmer et exécuter</strong>.</li></ol>',12)),o(s,{name:"release-recap",alt:"Le récapitulatif avant exécution : cible, version, tag, dépôt, branche et étapes"}),e[3]||(e[3]=n('<p>Le résultat s&#39;affiche étape par étape : <strong>fait</strong>, <strong>à faire à la main</strong> (le moteur n&#39;a pas pu agir et dit pourquoi, par exemple sans <code>gh</code>), <strong>échec</strong>, ou <strong>non jouée</strong> (une étape précédente a échoué : la chaîne s&#39;arrête).</p><p>En mode de travail semi-auto, l&#39;exécution est refusée et le panneau le dit.</p><p>Un tag n&#39;est jamais posé sur des fichiers non commités : sans <strong>Commit et push</strong>, la nouvelle version ne serait pas dans le commit tagué. L&#39;étape échoue alors et le dit.</p><h3 id="livrer-en-interne-ou-en-public" tabindex="-1">Livrer en interne ou en public <a class="header-anchor" href="#livrer-en-interne-ou-en-public" aria-label="Permalink to &quot;Livrer en interne ou en public&quot;">​</a></h3><p>Sous la cible, choisissez le <strong>Canal</strong> :</p><ul><li><strong>Interne</strong> : la livraison décrite plus haut. La release et ses artefacts vont au <strong>Dépôt de release</strong> interne (par défaut, le dépôt d&#39;origine du code).</li><li><strong>Public</strong> : on publie une version <strong>déjà livrée en interne</strong>, telle quelle — même tag, mêmes artefacts, sans nouveau bump. L&#39;écran ne propose que les versions livrées en interne et pas encore publiques. Si aucun dépôt public n&#39;est déclaré pour la cible, il le dit et renvoie à la configuration plus bas.</li></ul><p>Pour publier :</p><ol><li>Cliquez sur <strong>Publier…</strong> à côté de la version.</li><li>Le panneau rappelle le tag, le dépôt d&#39;où elle vient et celui où elle va. La publication est publique et irréversible.</li><li>Tapez le tag dans le champ <strong>Tapez … pour confirmer</strong> : le bouton <strong>Publier</strong> ne s&#39;active qu&#39;à ce moment.</li></ol><p>Le moteur refuse, en le disant, si la release n&#39;existe pas sur le canal interne, si elle est déjà publique, ou en mode semi-auto.</p>',9)),o(s,{name:"release-public",alt:"Le canal Public : versions livrées en interne, prêtes à publier"}),e[4]||(e[4]=n('<h3 id="configurer-la-livraison" tabindex="-1">Configurer la livraison <a class="header-anchor" href="#configurer-la-livraison" aria-label="Permalink to &quot;Configurer la livraison&quot;">​</a></h3><ol><li>Cliquez sur un module dans <strong>Stacks configurés</strong> pour préremplir le formulaire, ou renseignez son nom dans <strong>Stack</strong>.</li><li>Indiquez la <strong>Commande de build</strong>, par exemple <code>pnpm build</code>. Pour un module, elle se joue dans son répertoire.</li><li>Listez les <strong>Artefacts</strong>, par exemple <code>dist/*.zip</code>. Laisser ce champ vide conserve ceux déjà enregistrés.</li><li>Cliquez sur <strong>Enregistrer la livraison</strong>.</li></ol><p>Plus bas, <strong>Canaux de livraison</strong> règle les deux dépôts de release de la cible : <strong>Dépôt de release interne</strong> (<code>owner/nom</code> ; vide = le dépôt d&#39;origine) et <strong>Dépôt de release public</strong> (<code>owner/nom</code> ; vide = pas de livraison publique). Cliquez sur <strong>Enregistrer les canaux</strong>.</p><h3 id="relire-l-historique" tabindex="-1">Relire l&#39;historique <a class="header-anchor" href="#relire-l-historique" aria-label="Permalink to &quot;Relire l&#39;historique&quot;">​</a></h3><p><strong>Historique des livraisons</strong>, en bas de l&#39;écran, liste chaque livraison exécutée, avec ses colonnes <strong>Date</strong>, <strong>Canal</strong> (interne ou public), <strong>Cible</strong>, <strong>Tag</strong> (lien vers la release quand il existe), <strong>Dépôt</strong> et <strong>Issue</strong> (<strong>livrée</strong> ou <strong>arrêtée</strong>). Il vit dans <code>.effortless/deliveries.json</code>, versionné avec le projet.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Un agent fait la même chose par <code>effortless_release_plan</code> (le plan) et <code>effortless_release_apply</code> (l&#39;exécution, après votre accord). Les deux prennent <code>stack</code> pour viser un module. Il configure la livraison par <code>effortless_release_delivery_set</code> et les canaux par <code>effortless_release_channels_set</code>. Il publie par <code>effortless_release_promote</code>, qui exige de redonner le tag dans <code>confirm</code> — après votre accord explicite. Il lit l&#39;historique par <code>effortless_deliveries</code>.</p>',7))])}const q=a(d,[["render",c]]);export{b as __pageData,q as default};
